Get proof goals at a position. MOST IMPORTANT tool - use often!

    Omit column to see goals_before (line start) and goals_after (line end),
    showing how the tactic transforms the state. status='complete' means the
    proof is finished at this point; status='no_goal_at_position' means the
    position carries no proof state (e.g. outside a proof).


exec tool declaration:
```ts
declare const tools: { mcp__lean_lsp__lean_goal(args: {
  // Column (1-indexed). Omit for before/after
  column?: number | null;
  // Absolute or project-root-relative path to Lean file
  file_path: string;
  // Output format: 'text' (default) or 'structured'
  format?: "text" | "structured";
  // Line number (1-indexed)
  line: number;
  // Max seconds to wait for elaboration. On timeout returns status='still_elaborating' - poll again.
  timeout_s?: number | null;
}): Promise<CallToolResult<{
  // Goal list at specified column position
  goals?: Array<string | unknown> | null;
  // Goals at line end (when column omitted)
  goals_after?: Array<string | unknown> | null;
  // Goals at line start (when column omitted)
  goals_before?: Array<string | unknown> | null;
  // Source line where goals were queried
  line_context: string;
  // Goal status: 'goals' (open goals), 'complete' (no goals left - proof finished here), 'no_goal_at_position' (position carries no proof state), or 'still_elaborating' (timeout_s hit - poll again)
  status?: string | null;
}>>; };
```"}]

